package wgmodern;
import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.gui.Font;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;
public class CameraRenderer extends BlockEntityWithoutLevelRenderer {
 private static CameraRenderer instance;private static final ResourceLocation OBJ=new ResourceLocation("witchinggadgets","models/scancamera.obj"),GOLD=new ResourceLocation("thaumcraft","textures/models/scanner.png"),LEATHER=new ResourceLocation("witchinggadgets","textures/models/cameraleather.png"),SCREEN=new ResourceLocation("thaumcraft","textures/models/scanscreen.png"),WOOD=new ResourceLocation("thaumcraft","textures/block/planks_greatwood.png");
 public CameraRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}public static CameraRenderer instance(){if(instance==null)instance=new CameraRenderer();return instance;}
 @Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack pose,MultiBufferSource buffers,int light,int overlay){pose.pushPose();pose.translate(.5,.5,.5);switch(context){case GUI->{/* Legacy INVENTORY_BLOCK helper, followed by camera scale. */pose.scale(.625f,-.625f,-.625f);pose.mulPose(Axis.XP.rotationDegrees(210));pose.mulPose(Axis.YP.rotationDegrees(-45));pose.scale(2,2,2);}case GROUND->{pose.scale(2,2,2);pose.translate(0,.125,0);}case FIXED->{pose.scale(1.5f,1.5f,1.5f);}case THIRD_PERSON_LEFT_HAND,THIRD_PERSON_RIGHT_HAND->{pose.mulPose(Axis.YP.rotationDegrees(45));pose.mulPose(Axis.XP.rotationDegrees(-70));pose.scale(2,1.5f,-1.5f);pose.translate(-.5,-.875,-.1);pose.translate(.6,.15,.005);pose.scale(.875f,1.75f,1.75f);}default->{pose.scale(2,2,2);}}draw(pose,buffers,light,overlay,false);pose.popPose();}
 public static void draw(PoseStack p,MultiBufferSource buffers,int light,int overlay,boolean lens){var model=LegacyObj.get(OBJ);model.draw("Gold_01",p,buffers.getBuffer(RenderType.entityCutoutNoCull(GOLD)),light,overlay,0xffffff,1);if(lens){p.pushPose();p.scale(1.75f,1,1);p.translate(.1,0,0);model.draw("Display_00",p,buffers.getBuffer(RenderType.entityCutoutNoCull(GOLD)),light,overlay,0x999999,1);p.popPose();}model.draw("Leather_02",p,buffers.getBuffer(RenderType.entityCutoutNoCull(LEATHER)),light,overlay,0xffffff,1);model.draw("Wood_04",p,buffers.getBuffer(RenderType.entityCutoutNoCull(WOOD)),light,overlay,0xffffff,1);p.pushPose();if(lens)p.scale(1,-1,1);model.draw("Scanner_03",p,buffers.getBuffer(RenderType.entityTranslucent(SCREEN)),light,overlay,0xffffff,1);if(lens){p.scale(.375f,.375f,-.375f);p.mulPose(Axis.YP.rotationDegrees(90));p.scale(.45f,.45f,.45f);p.mulPose(Axis.XP.rotationDegrees(-50));p.translate(0,-.2,-1.8);lens(p,buffers,overlay);}p.popPose();}
 private static void lens(PoseStack p,MultiBufferSource buffers,int overlay){var data=CameraClient.preview();if(!PhotoData.valid(data))return;var mc=Minecraft.getInstance();var aspects=PhotoData.aspects(data);int x=0,y=0,remaining=aspects.aspects().size(),half=Math.min(5,remaining)*8;for(var a:aspects.alphabetical()){p.pushPose();p.scale(.0075f,.0075f,.0075f);int px=-half+x*16,py=-8+y*16;quad(p,buffers,a.texture(),px,py,16,16,.01f,a.color(),240,overlay,true);var count=""+aspects.amount(a);p.pushPose();p.scale(.5f,.5f,.5f);mc.font.drawInBatch(count,px*2+32-mc.font.width(count),py*2+32-mc.font.lineHeight,0xffffff,false,p.last().pose(),buffers,Font.DisplayMode.NORMAL,0,LightTexture.FULL_BRIGHT);p.popPose();p.popPose();if(++x>=Math.max(1,5-y)){x=0;y++;remaining-=Math.max(1,5-y);half=Math.min(Math.max(1,5-y),remaining)*8;}}
 var name=PhotoData.name(data);int width=mc.font.width(name);float scale=Math.max(.0005f,.005f-Math.max(0,width-90)*.000025f);p.pushPose();p.translate(0,-.25,0);p.scale(scale,scale,scale);mc.font.drawInBatch(name,-width/2f,0,0xffffff,true,p.last().pose(),CameraTextRender.additive(buffers),Font.DisplayMode.NORMAL,0,LightTexture.FULL_BRIGHT);p.popPose();}
 public static void quad(PoseStack p,MultiBufferSource buffers,ResourceLocation texture,float x,float y,float w,float h,float z,int rgb,int light,int overlay,boolean additive){var out=buffers.getBuffer(additive?tc4revival.client.TCRenderTypes.lens(texture):RenderType.entityTranslucent(texture));for(float[] v:new float[][]{{x,y+h,0,1},{x+w,y+h,1,1},{x+w,y,1,0},{x,y,0,0}}){var vertex=out.vertex(p.last().pose(),v[0],v[1],z).color(rgb>>16&255,rgb>>8&255,rgb&255,255).uv(v[2],v[3]);if(!additive)vertex.overlayCoords(overlay);vertex.uv2(light);if(!additive)vertex.normal(p.last().normal(),0,0,-1);vertex.endVertex();}}
}
